  "headline": "Zoledronic acid is not on FDA's shortage list as of 2026-10-21; current supply at Corvale East covers 11 days and Corvale General covers 31.7 days",
  "headline_cites": ["D3", "D1", "D2"],
  "sentences": [
    {
      "text": "FDA's drug shortage list shows zoledronic acid is not listed as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "Corvale East holds 36 vials of the 4 mg/100 mL presentation with a daily use of 3.3 vials, providing 11 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 89 vials of the same presentation with a daily use of 2.8 vials, providing 31.7 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "The ranked purchasing options are Accord Healthcare Inc. first, AuroMedics Pharma LLC second, and Avenacy Inc. third; none are on FDA's shortage list today and their labels name no plant we could place.",
      "cites": ["D4", "D5", "D6"]
    },
    {
      "text": "A label for zoledronic acid names Gland Pharma Limited as the manufacturing plant (FEI 3002647489) with a registered plant link and a most recent VAI inspection ending 2024-07-25.",
      "cites": ["E9"]
    },
    {
      "text": "FDA inspection records for that plant show a series of VAI classifications from 2012 through 2024, with the latest known date 2025-01-15.",
      "cites": ["E3", "E4", "E5", "E6", "E7", "E8"]
    }
  ]
}
